<?php
require __DIR__.'/bootstrap.php';session_start_safe();$_SESSION['admin']=1;$action=$argv[1]??'';
function scr_session(?string $rid=null,int $limit=3): string {$_SESSION['workflow_actor']=bin2hex(random_bytes(32));return vs_create(['scope_kind'=>$rid?'research':'all','research_id'=>$rid??'','session_preset'=>'custom','minutes'=>60,'assignment_limit'=>8,'concurrent_limit'=>$limit,'worker_choice'=>'astra_max','authorize'=>1,'terms'=>1,'authorized_resources'=>1,'policy_version'=>terms_version()])['id'];}
if($action==='create'){$projects=[];for($i=0;$i<7;$i++){$m=create_research(['title'=>'[QA] Session capacity '.uid(),'question'=>'Synthetic concurrent reservation/Stop fixture, no scientific or native AI claim.','category_id'=>1,'terms'=>1]);$projects[]=$m['id'];moderate('request',$m['id'],'Approved','Owned session capacity fixture.');}$parallel=scr_session();$legacy=scr_session(null,1);$owner1=scr_session($projects[6]);$owner2=scr_session($projects[6]);echo json_encode(['projects'=>$projects,'sessions'=>[$parallel,$legacy,$owner1,$owner2]]);exit;}
if($action==='worker'){$d=json_decode(stream_get_contents(STDIN),true,16,JSON_THROW_ON_ERROR);$s=vs_read($d['session'],false);$_SESSION['volunteer_sessions'][$s['id']]=$s['secret_hash'];$dir=realpath(storage('qa/session-capacity-race'));if(!$dir||realpath(dirname($d['gate']))!==$dir||realpath(dirname($d['ready']))!==$dir)throw new RuntimeException('Unsafe test barrier.');file_put_contents($d['ready'],'ready');$deadline=microtime(true)+12;while(!is_file($d['gate'])){if(microtime(true)>$deadline)throw new RuntimeException('Test barrier timed out.');usleep(10000);}try{$value=match($d['operation']){'claim'=>vs_claim_next($s['id'],$d['key'])['id'],'stop'=>(function()use($s){vs_stop($s['id']);return 'stopped';})(),'release','renew'=>(function()use($s,$d){vs_assignment_action($s['id'],$d['assignment'],$d['operation']);return $d['operation'];})(),default=>throw new RuntimeException('Unknown operation')};echo json_encode(['status'=>200,'result'=>$value]);}catch(HttpError $e){echo json_encode(['status'=>$e->status,'error'=>$e->getMessage()]);}exit;}
if($action==='state'){$s=vs_read($argv[2],false);echo json_encode(['used'=>(int)$s['assignments_used'],'assignments'=>all('SELECT id,claim_key,ended_at FROM volunteer_assignments WHERE session_id=? ORDER BY created_at,id',[$s['id']]),'active'=>count(vs_active_assignments($s)),'leases'=>(int)one('SELECT COUNT(*) n FROM task_reservations WHERE actor_hash=? AND ended_at IS NULL AND expires_at>?',[$s['actor_hash'],wr_stamp()])['n'],'stopped'=>(bool)$s['stopped_at']]);exit;}
if($action==='cleanup'){$d=json_decode(stream_get_contents(STDIN),true,12,JSON_THROW_ON_ERROR);foreach($d['sessions'] as $id){$s=vs_read($id,false);$_SESSION['volunteer_sessions'][$id]=$s['secret_hash'];vs_stop($id);query('DELETE FROM volunteer_sessions WHERE id=?',[$id]);}foreach($d['projects'] as $rid){if(!one("SELECT id FROM research WHERE id=? AND title LIKE '[QA] Session capacity %'",[$rid]))throw new RuntimeException('Not an owned fixture');purge_request($rid,$rid);}exit;}throw new RuntimeException('Unknown fixture operation');
